import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

export const LANGUAGE_STORAGE_KEY = 'tripreel-language';

export const supportedLanguages = [
  'ar', 'ca', 'cs', 'da', 'de', 'el', 'en', 'es', 'fi', 'fr',
  'he', 'hi', 'hr', 'hu', 'id', 'it', 'ja', 'ko', 'ms', 'nl',
  'no', 'pl', 'pt', 'ro', 'ru', 'sk', 'sv', 'th', 'tr', 'uk',
  'vi', 'zh'
];

export const rtlLanguages = ['ar', 'he'];

// Lazy load translation files on-demand
const loadLanguageResources = async (lng) => {
  try {
    const module = await import(`./locales/${lng}.json`);
    return module.default;
  } catch (error) {
    console.error(`Failed to load language: ${lng}`, error);
    // Fallback to English if loading fails
    if (lng !== 'en') {
      const fallback = await import('./locales/en.json');
      return fallback.default;
    }
    throw error;
  }
};

// Initialize with the detected language resource only
export const initializeI18n = async (initialLanguage = 'en') => {
  const translation = await loadLanguageResources(initialLanguage);
  
  await i18n
    .use(initReactI18next)
    .init({
      resources: {
        [initialLanguage]: { translation }
      },
      lng: initialLanguage,
      fallbackLng: 'en',
      interpolation: {
        escapeValue: false
      },
      react: {
        useSuspense: false
      }
    });

  return i18n;
};

// Load additional language resources dynamically
export const changeLanguage = async (lng) => {
  if (!i18n.hasResourceBundle(lng, 'translation')) {
    const translation = await loadLanguageResources(lng);
    i18n.addResourceBundle(lng, 'translation', translation);
  }
  await i18n.changeLanguage(lng);
};

export default i18n;
